func (s *Server) syncEditedSubTasksToLLMAnalysis(taskKey string, items []SubTaskDTO) {
	storedLLM := s.loadTaskLLMAnalysis(taskKey)
	if storedLLM == nil {
		return
	}
	specs := make([]ArchitectLLMSubTaskSpec, 0, len(items))
	for _, it := range items {
		specs = append(specs, ArchitectLLMSubTaskSpec{
			SubTaskID:       it.SubTaskID,
			Title:           it.Title,
			Description:     it.Description,
			ContextFileLine: it.ContextFileLine,
		})
	}
	storedLLM.SubTasks = specs

